      try {
        // 强制容器样式
        containerEl.style.height = '400px';
        containerEl.style.width = '100%';
        containerEl.style.overflow = 'visible';

        // 创建地图
        const map = new AMap.Map(containerEl, {
          zoom: 12,
          center: [attractions[0].longitude, attractions[0].latitude],
          mapStyle: 'amap://styles/light',
          resizeEnable: true,
          zoomEnable: false,
          // 导出时禁止缩放，保证截图稳定
          dragEnable: false
        });
        this.$set(this.maps, dayNum, map);
        const path = attractions.map(p => [p.longitude, p.latitude]);

        // 绘制路线
        const polyline = new AMap.Polyline({
          path: path,
          strokeColor: '#FF7A2F',
          strokeWeight: 4
        });
        map.add(polyline);

        // 添加标记点
        attractions.forEach((point, index) => {
          let offsetX = 0,
            offsetY = 0;
          if (index > 0) {
            const prev = attractions[index - 1];
            const dist = Math.pow(point.longitude - prev.longitude, 2) + Math.pow(point.latitude - prev.latitude, 2);
            if (dist < 0.000004) {
              offsetX = (index % 2 ? 1 : -1) * 0.00015;
              offsetY = (index % 2 ? 1 : -1) * 0.00015;
            }
          }

          // 序号标记
          const marker = new AMap.Marker({
            position: [point.longitude + offsetX, point.latitude + offsetY],
            content: `<div style="background:#FF7A2F;color:white;width:28px;height:28px;border-radius:50%;display:flex;align-items:center;justify-content:center;font-weight:bold;border:3px solid #fff;">${index + 1}</div>`,
            offset: new AMap.Pixel(-14, -14)
          });
          map.add(marker);

          // 名称标签
          const label = new AMap.Marker({
            position: [point.longitude + offsetX, point.latitude + offsetY],
            content: `<div style="background:#fff;padding:4px 8px;border-radius:4px;font-size:12px;box-shadow:0 1px 4px #00000026;">${point.name}</div>`,
            offset: new AMap.Pixel(-60, 18)
          });
          map.add(label);
        });
        map.setFitView();
        setTimeout(() => map.resize(), 100);
      } catch (error) {
        console.error('导出地图初始化失败:', error);
      }
    }
  }
};
